#[derive(Clone,Copy,PartialEq,Eq)]enum Phase{Bind,Reference,Capability,Ready,Closed}
pub struct ChildVectorReadCursor{binding:Option<RetainedCloneBinding>,lender:Option<&'static dyn ChildVectorReferenceLenderV1>,phase:Phase,ordinal:usize,field:usize,offset:usize,reference:usize,parent:usize,child:usize,capability:usize,parent_revision:[u8;32],child_revision:[u8;32],closing:bool}
pub struct ChildVectorReadAdvance{pub progress:RetainedCloneProgress,pub stamp:Option<ChildVectorReadStamp>}
impl ChildVectorReadCursor{
 const HEADER:usize=2*std::mem::size_of::<Self>();
 pub fn birth_demand()->RetirementDemand{RetirementDemand{copy_bytes:Self::HEADER,depth:1,..Default::default()}}
 pub fn admit(g:RetainedCloneGrant)->Result<(Self,RetainedCloneProgress),ValueError>{let d=Self::birth_demand();if !retained_clone_grant_admits(g,d){return Err(refusal("Original vector read qualification birth is unfunded"))}Ok((Self{binding:None,lender:None,phase:Phase::Bind,ordinal:0,field:0,offset:0,reference:0,parent:0,child:0,capability:0,parent_revision:[0;32],child_revision:[0;32],closing:false},RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))}
 fn nested(d:RetirementDemand)->Result<RetirementDemand,ValueError>{Ok(RetirementDemand{copy_bytes:d.copy_bytes.checked_add(Self::HEADER).ok_or_else(||refusal("Original vector qualification copy extent overflow"))?,depth:d.depth.checked_add(1).ok_or_else(||refusal("Original vector qualification depth overflow"))?,..d})}
 fn child(g:RetainedCloneGrant)->RetainedCloneGrant{RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes.saturating_sub(Self::HEADER),maximum_depth:g.maximum_depth.saturating_sub(1),..g}}
 fn paid(mut p:RetainedCloneProgress)->RetainedCloneProgress{p.copied_items=p.copied_items.max(1);p.copied_bytes=p.copied_bytes.saturating_add(Self::HEADER);p}
 fn failure(error:ValueError)->ValueError{let p=Self::paid(error.retained_progress());error.with_retained_progress(p)}
 fn verify(&self,parent:ChildAdmissionSource<'_>,lender:&'static dyn ChildVectorReferenceLenderV1,ordinal:usize,current:ChildMemberReadMetadata<'_>,capability:&'static ChildVectorReadCapability)->Result<(),ValueError>{if self.closing||self.phase==Phase::Closed{return Err(refusal("Original vector read qualification is closing"))}if self.binding.is_some(){parent.binding_demand(&self.binding)?;if !std::ptr::eq(self.lender.unwrap(),lender)||self.ordinal!=ordinal||self.parent!=current.parent_identity||self.child!=current.child_identity||self.capability!=capability as*const _ as usize||self.parent_revision!=*current.parent_revision||self.child_revision!=*current.child_revision{return Err(refusal("Original vector read qualification source changed"))}}Ok(())}
 pub fn next_demand<S>(&self,parent:ChildAdmissionSource<'_>,lender:&'static dyn ChildVectorReferenceLenderV1,ordinal:usize,read:&ChildEditorRead<'_,S>,capability:&'static ChildVectorReadCapability)->Result<RetirementDemand,ValueError>{self.verify(parent,lender,ordinal,read.member_metadata(),capability)?;if self.phase==Phase::Bind{Self::nested(parent.binding_demand(&self.binding)?.unwrap_or_default())}else{Self::nested(lender.demand(ordinal))}}
 fn current_text<'a>(current:ChildMemberReadMetadata<'a>,at:usize)->&'a str{match at{0=>current.owner,1=>current.slot,2=>current.child_id,3=>current.artifact_id,4=>current.artifact_kind,5=>current.standard,6=>current.subset,_=>unreachable!()}}
 fn equal_one(left:&str,right:&str,offset:&mut usize)->Result<bool,ValueError>{if left.len()!=right.len(){return Err(refusal("Original child reference differs from the actual member"))}if *offset==left.len(){*offset=0;return Ok(true)}if left.as_bytes()[*offset]!=right.as_bytes()[*offset]{return Err(refusal("Original child reference differs from the actual member"))}*offset+=1;Ok(false)}
 fn advance<S>(&mut self,parent:ChildAdmissionSource<'_>,lender:&'static dyn ChildVectorReferenceLenderV1,ordinal:usize,read:&ChildEditorRead<'_,S>,capability:&'static ChildVectorReadCapability,g:RetainedCloneGrant)->Result<ChildVectorReadAdvance,ValueError>{let d=self.next_demand(parent,lender,ordinal,read,capability)?;if !retained_clone_grant_admits(g,d){return Ok(ChildVectorReadAdvance{progress:Default::default(),stamp:None})}let child=Self::child(g);let current=read.member_metadata();if self.phase==Phase::Bind{let p=parent.bind(&mut self.binding,child).map_err(Self::failure)?.unwrap_or_default();self.lender=Some(lender);self.ordinal=ordinal;self.parent=current.parent_identity;self.child=current.child_identity;self.capability=capability as*const _ as usize;self.parent_revision=*current.parent_revision;self.child_revision=*current.child_revision;self.phase=Phase::Reference;return Ok(ChildVectorReadAdvance{progress:Self::paid(p),stamp:None})}let step=lender.read(parent,ordinal,child).map_err(Self::failure)?;let p=Self::paid(step.progress);if !step.progress.fits(child){return Err(refusal("Original reference lender receipt exceeds its grant").with_retained_progress(p))}if !step.done{return Ok(ChildVectorReadAdvance{progress:p,stamp:None})}let reference=step.reference.ok_or_else(||refusal("Original parent has no requested child reference").with_retained_progress(p))?;if reference.parent_identity!=current.parent_identity||reference.parent_identity!=parent.reference_identity().2||reference.identity==0||self.reference!=0&&self.reference!=reference.identity{return Err(refusal("Original parent or member reference changed").with_retained_progress(p))}self.reference=reference.identity;
 let accepted=match self.phase{Phase::Reference=>{let same=Self::equal_one(reference.text(self.field),Self::current_text(current,self.field),&mut self.offset).map_err(|error|error.with_retained_progress(p))?;if same{self.field+=1;if self.field==7{self.phase=Phase::Capability;self.field=0}}false},Phase::Capability=>{let (left,right)=match self.field{0=>(current.artifact_kind,capability.artifact_kind),1=>(current.standard,capability.standard),_=>(current.subset,capability.subset)};if Self::equal_one(left,right,&mut self.offset).map_err(|error|error.with_retained_progress(p))?{self.field+=1;if self.field==3{self.phase=Phase::Ready}}false},Phase::Ready=>true,_=>unreachable!()};Ok(ChildVectorReadAdvance{progress:p,stamp:accepted.then(||ChildVectorReadStamp{original:parent.reference_identity(),ordinal:self.ordinal,reference:self.reference,parent:self.parent,child:self.child,capability:self.capability,parent_revision:self.parent_revision,child_revision:self.child_revision})})}
 pub fn begin_close(&mut self){self.closing=true}
 pub fn close_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{if self.phase==Phase::Closed{return Ok(Default::default())}if self.binding.is_some(){Self::nested(RetainedCloneBinding::close_demand(&self.binding,body.saturating_sub(Self::HEADER))?)}else{Ok(Self::birth_demand())}}
 pub fn close_step(&mut self,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{if !self.closing{return Err(refusal("Original vector read qualification closure has not begun"))}if self.phase==Phase::Closed{return Ok(RetainedCloneStep::Complete(Default::default()))}let d=self.close_demand(g.maximum_copy_bytes)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}if self.binding.is_some(){let p=RetainedCloneBinding::close_one(&mut self.binding,Self::child(g)).map_err(Self::failure)?.progress();return Ok(RetainedCloneStep::Progress(Self::paid(p)))}self.lender=None;self.phase=Phase::Closed;Ok(RetainedCloneStep::Complete(Self::paid(Default::default())))}
 pub fn terminal_is_empty(&self)->bool{self.phase==Phase::Closed&&self.binding.is_none()&&self.lender.is_none()}
}
impl Drop for ChildVectorReadCursor{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"Original vector read qualification requires funded source closure")}}
struct CursorRetirement{cursor:Option<ChildVectorReadCursor>}
impl RetireOwned for ChildVectorReadCursor{fn retirement(self)->Box<dyn RetirementCursor>{Box::new(CursorRetirement{cursor:Some(self)})}fn retirement_birth_bytes(&self)->Option<usize>{Some(std::mem::size_of::<CursorRetirement>())}fn controlled_retirement_supported()->bool{true}}
impl RetirementCursor for CursorRetirement{fn next_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{self.cursor.as_ref().map_or(Ok(Default::default()),|cursor|cursor.close_demand(body))}fn close_step(&mut self,g:RetainedCloneGrant)->RetirementStep{let Some(cursor)=self.cursor.as_mut()else{return RetirementStep::Complete};cursor.begin_close();match cursor.close_step(g){Err(error)=>RetirementStep::Failure(error),Ok(step)=>{let p=step.progress();if cursor.terminal_is_empty(){self.cursor=None}RetirementStep::Progress(p)}}}fn terminal_is_empty(&self)->bool{self.cursor.is_none()}fn terminal_release_bytes(&self)->Option<usize>{Some(std::mem::size_of::<Self>())}}
pub struct ChildVectorReadRegistration<S>{pub identity:ChildVectorReadCapability,pub admission:&'static dyn EmbeddedChildAdmitterV1,pub vector:&'static dyn EmbeddedChildVectorSourceV1,marker:std::marker::PhantomData<fn()->S>}
