impl<S: RetireOwned + ::semio_framework_os_kernel::StoreState> ChildVectorReadRegistration<S>{pub fn admission_provider<'a>(&'static self,custody:&'a ChildVectorSourceCustody<S>,ordinal:usize,g:RetainedCloneGrant)->Result<(ChildVectorAdmissionProvider<'a,S>,RetainedCloneProgress),ValueError>{ChildVectorAdmissionProvider::admit(custody,self,ordinal,g)}pub fn admit_original_source(&'static self,read:&ChildEditorRead<'_,S>,stamp:&ChildVectorReadStamp,custody:&mut ChildVectorSourceCustody<S>,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{read.admit_qualified_source(&self.identity as*const _ as usize,stamp,custody,g)}}
pub type ChildVectorAdmissionProvider<'a,S:RetireOwned+Sync>=super::child_editor::read::admission::QualifiedChildAdmissionProvider<'a,S,ChildVectorReadStamp>;
impl<'a,S: RetireOwned + ::semio_framework_os_kernel::StoreState> super::child_editor::read::admission::QualifiedChildAdmissionProvider<'a,S,ChildVectorReadStamp>{pub fn admit(custody:&'a ChildVectorSourceCustody<S>,registration:&'static ChildVectorReadRegistration<S>,ordinal:usize,g:RetainedCloneGrant)->Result<(Self,RetainedCloneProgress),ValueError>{if !retained_clone_grant_admits(g,Self::demand()){return Err(refusal("Qualified child admission provider birth is unfunded"))}if custody.stamp().is_some_and(|stamp|stamp.ordinal!=ordinal){return Err(refusal("Original vector provider ordinal differs from its qualified reference").with_retained_progress(RetainedCloneProgress{copied_items:1,copied_bytes:Self::demand().copy_bytes-ChildAdmissionAddress::demand().copy_bytes,..Default::default()}))}Self::admit_registered(custody,&registration.identity as*const _ as usize,registration.admission,registration.vector,ordinal,g)}}


